import Model from 'flarum/common/Model';
/** A row on the collectors board (sticker-book-collectors): a member and how many different stickers they have. */
export default class Collector extends Model {
  uniqueCount() {
    return Model.attribute('uniqueCount').call(this);
  }
  /** How many stickers there are to collect. */
  total() {
    return Model.attribute('total').call(this);
  }
  user() {
    return Model.hasOne('user').call(this) || null;
  }
}
flarum.reg.add('ernestdefoe-sticker-book', 'common/models/Collector', Collector);