import Model from 'flarum/common/Model';
/** An offer of spares between two members (sticker-book-trades): only they can see it. */
export default class Trade extends Model {
  status() {
    return Model.attribute('status').call(this);
  }
  /** What the sender gives. */
  give() {
    return Model.attribute('give').call(this);
  }
  /** What the sender asks for. */
  take() {
    return Model.attribute('take').call(this);
  }
  message() {
    return Model.attribute('message').call(this);
  }
  /** The stickers on both sides, with their art. */
  stickers() {
    return Model.attribute('stickers').call(this);
  }
  createdAt() {
    return Model.attribute('createdAt', Model.transformDate).call(this);
  }
  decidedAt() {
    return Model.attribute('decidedAt', Model.transformDate).call(this);
  }
  from() {
    return Model.hasOne('from').call(this) || null;
  }
  to() {
    return Model.hasOne('to').call(this) || null;
  }
}
flarum.reg.add('ernestdefoe-sticker-book', 'common/models/Trade', Trade);